=== budget ===
//! Token estimation, depth levels, the skeletonizer and the budget cut (ported from
//! eckSnapshot's `depthConfig.js`, `snapshotBuilder.js` metrics and `skeletonizer.js`).
//!
//! The token estimate is eckSnapshot's `chars / 4` with a small per-extension factor. The
//! depth scale is 0â€“9: tree only, line-truncation, skeleton (signatures only), skeleton +
//! docs, then full with increasing line caps. The skeletonizer here is deliberately
//! lexical â€” it keeps lines that *look* like declarations for Rust/JS/TS/Python and drops
//! bodies with an explicit `[... N lines omitted ...]` marker. Its limits are documented on
//! [`skeletonize`]: it is not a parser, so a body line that happens to look like a
//! declaration is kept, and a declaration split across lines may be cut.

/// The rendered depth configuration for one level (eckSnapshot `getDepthConfig`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Depth {
    pub level: u8,
    /// Tree only, no file bodies.
    pub tree_only: bool,
    /// Keep only signature-like lines.
    pub skeleton: bool,
    /// In skeleton mode, keep doc comments too.
    pub preserve_docs: bool,
    /// Truncate a body to this many lines (`0` = no cap).
    pub max_lines: usize,
}

/// Resolve a depth level 0â€“9 (clamped) to its configuration.
pub fn depth(level: u8) -> Depth {
    let d = level.min(9);
    match d {
        0 => Depth {
            level: 0,
            tree_only: true,
            skeleton: false,
            preserve_docs: false,
            max_lines: 0,
        },
        1..=4 => Depth {
            level: d,
            tree_only: false,
            skeleton: false,
            preserve_docs: false,
            max_lines: match d {
                1 => 10,
                2 => 30,
                3 => 60,
                _ => 100,
            },
        },
        5 => Depth {
            level: 5,
            tree_only: false,
            skeleton: true,
            preserve_docs: false,
            max_lines: 0,
        },
        6 => Depth {
            level: 6,
            tree_only: false,
            skeleton: true,
            preserve_docs: true,
            max_lines: 0,
        },
        7 => Depth {
            level: 7,
            tree_only: false,
            skeleton: false,
            preserve_docs: false,
            max_lines: 500,
        },
        8 => Depth {
            level: 8,
            tree_only: false,
            skeleton: false,
            preserve_docs: false,
            max_lines: 1000,
        },
        _ => Depth {
            level: 9,
            tree_only: false,
            skeleton: false,
            preserve_docs: false,
            max_lines: 0,
        },
    }
}

/// A per-extension multiplier on the base `chars / 4` estimate.
fn ext_factor(ext: &str) -> f64 {
    match ext.to_ascii_lowercase().as_str() {
        // Prose tokenizes a little denser than the 1/4 rule; markup/JSON a little coarser.
        "md" | "markdown" | "txt" | "rst" => 1.05,
        "json" | "yaml" | "yml" | "toml" | "lock" => 0.9,
        _ => 1.0,
    }
}

/// Approximate token count for `text` of the given file extension (empty for none).
/// eckSnapshot's `Math.round(content.length / 4)` with the per-extension factor.
pub fn estimate_tokens(text: &str, ext: &str) -> usize {
    let base = text.chars().count() as f64 / 4.0;
    (base * ext_factor(ext)).round() as usize
}

/// The extension of a repo-relative path (`""` for none), lowercased without the dot.
pub fn ext_of(rel: &str) -> String {
    rel.rsplit('/')
        .next()
        .and_then(|name| name.rsplit_once('.').map(|(_, e)| e.to_ascii_lowercase()))
        .unwrap_or_default()
}

/// Truncate `content` to `max_lines`, appending an explicit omission marker (eckSnapshot's
/// `// ... truncated (N more lines)`), C3 uses the `[... N lines omitted ...]` marker the
/// design names). `0` means no cap.
pub fn truncate_lines(content: &str, max_lines: usize) -> String {
    if max_lines == 0 {
        return content.to_string();
    }
    let lines: Vec<&str> = content.lines().collect();
    if lines.len() <= max_lines {
        return content.to_string();
    }
    let kept = &lines[..max_lines];
    format!(
        "{}\n[... {} lines omitted ...]",
        kept.join("\n"),
        lines.len() - max_lines
    )
}

/// A lexical skeletonizer for Rust / JS / TS / Python.
///
/// It keeps lines that look like declarations (functions, types, imports, module/impl
/// headers, top-level constants, decorators/attributes) and doc/comment lines when
/// `preserve_docs`; every run of dropped lines becomes one `[... N lines omitted ...]`
/// marker. Files of other languages are returned unchanged (only line-truncated by the
/// caller).
///
/// Limits (by construction, not a bug): this is regex-per-line, not an AST. A body line
/// that begins like a declaration (`let handler = |x| {`) is kept; a declaration whose
/// signature wraps across lines keeps only its first line; brace matching is not tracked,
/// so a kept declaration does not pull in its closing brace. For a faithful skeleton use a
/// language server; this is the offline, dependency-free approximation.
pub fn skeletonize(content: &str, rel: &str, preserve_docs: bool) -> String {
    let ext = ext_of(rel);
    let lang = match ext.as_str() {
        "rs" => Lang::Rust,
        "js" | "jsx" | "mjs" | "cjs" | "ts" | "tsx" => Lang::Js,
        "py" => Lang::Py,
        _ => return content.to_string(),
    };

    let mut out: Vec<String> = Vec::new();
    let mut omitted = 0usize;
    let flush = |out: &mut Vec<String>, omitted: &mut usize| {
        if *omitted > 0 {
            out.push(format!("[... {} lines omitted ...]", *omitted));
            *omitted = 0;
        }
    };

    for line in content.lines() {
        if keep_line(line, lang, preserve_docs) {
            flush(&mut out, &mut omitted);
            out.push(line.to_string());
        } else {
            omitted += 1;
        }
    }
    flush(&mut out, &mut omitted);
    out.join("\n")
}

#[derive(Clone, Copy)]
enum Lang {
    Rust,
    Js,
    Py,
}

fn keep_line(line: &str, lang: Lang, preserve_docs: bool) -> bool {
    let t = line.trim_start();
    if t.is_empty() {
        return false;
    }
    // Doc / comment lines.
    let is_doc = matches!(lang, Lang::Rust)
        && (t.starts_with("///") || t.starts_with("//!") || t.starts_with("/**"))
        || matches!(lang, Lang::Js) && (t.starts_with("/**") || t.starts_with("* ") || t == "*/")
        || matches!(lang, Lang::Py) && (t.starts_with("\"\"\"") || t.starts_with("'''"));
    if is_doc {
        return preserve_docs;
    }

    match lang {
        Lang::Rust => {
            t.starts_with("use ")
                || t.starts_with("pub use ")
                || t.starts_with("mod ")
                || t.starts_with("pub mod ")
                || t.starts_with("#[")
                || t.starts_with("#![")
                || t.starts_with("extern crate")
                || starts_with_any(
                    t,
                    &[
                        "fn ",
                        "pub fn ",
                        "pub(crate) fn ",
                        "async fn ",
                        "pub async fn ",
                        "unsafe fn ",
                        "const fn ",
                        "pub const fn ",
                    ],
                )
                || starts_with_any(
                    t,
                    &[
                        "struct ",
                        "pub struct ",
                        "enum ",
                        "pub enum ",
                        "trait ",
                        "pub trait ",
                        "impl ",
                        "type ",
                        "pub type ",
                        "const ",
                        "pub const ",
                        "static ",
                        "pub static ",
                        "macro_rules!",
                    ],
                )
        }
        Lang::Js => {
            starts_with_any(
                t,
                &[
                    "import ",
                    "export ",
                    "function ",
                    "async function ",
                    "class ",
                    "export default",
                    "export class",
                    "export function",
                    "export async",
                    "export const",
                    "export interface",
                    "export type",
                    "export enum",
                    "interface ",
                    "type ",
                    "const ",
                    "let ",
                    "var ",
                    "public ",
                    "private ",
                    "protected ",
                    "static ",
                    "constructor(",
                    "async ",
                    "get ",
                    "set ",
                ],
            ) || t.starts_with("@")
        }
        Lang::Py => {
            starts_with_any(
                t,
                &["def ", "async def ", "class ", "import ", "from ", "@"],
            ) || (!t.starts_with(' ') && t.contains('=') && !t.contains("=="))
        }
    }
}

fn starts_with_any(t: &str, prefixes: &[&str]) -> bool {
    prefixes.iter().any(|p| t.starts_with(p))
}

/// One file offered to the budget cut.
#[derive(Debug, Clone)]
pub struct Candidate {
    pub rel: String,
    /// The already-rendered (redaction happens later) body of the file.
    pub body: String,
    /// Focus files are kept whole; periphery is trimmed first.
    pub focus: bool,
    /// Estimated tokens of the full body.
    pub tokens: usize,
}

/// The outcome of a budget cut.
#[derive(Debug, Clone, Default)]
pub struct BudgetPlan {
    /// Files kept in full, in the given order.
    pub full: Vec<String>,
    /// Files reduced to a skeleton because the full body did not fit.
    pub skeletonized: Vec<String>,
    /// Files dropped entirely (with a periphery omission note upstream).
    pub dropped: Vec<String>,
}

/// Decide how each candidate is rendered under a token `budget`.
///
/// Focus files are always kept whole (they are the point of the pack; the budget can be
/// exceeded by them, which the caller reports). Periphery files are added in the given
/// order while budget remains; a periphery file that does not fit whole is offered as a
/// skeleton if the skeleton fits, otherwise dropped. `budget == 0` keeps everything whole.
pub fn plan(candidates: &[Candidate], budget: usize) -> BudgetPlan {
    let mut plan = BudgetPlan::default();
    if budget == 0 {
        plan.full = candidates.iter().map(|c| c.rel.clone()).collect();
        return plan;
    }

    let mut used = 0usize;
    // Focus first, whole, always.
    for c in candidates.iter().filter(|c| c.focus) {
        plan.full.push(c.rel.clone());
        used += c.tokens;
    }
    // Periphery, in order, trimming to fit.
    for c in candidates.iter().filter(|c| !c.focus) {
        if used + c.tokens <= budget {
            plan.full.push(c.rel.clone());
            used += c.tokens;
            continue;
        }
        let skel = skeletonize(&c.body, &c.rel, false);
        let skel_tokens = estimate_tokens(&skel, &ext_of(&c.rel));
        if used + skel_tokens <= budget {
            plan.skeletonized.push(c.rel.clone());
            used += skel_tokens;
        } else {
            plan.dropped.push(c.rel.clone());
        }
    }
    plan
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn depth_scale() {
        assert!(depth(0).tree_only);
        assert_eq!(depth(2).max_lines, 30);
        assert!(depth(5).skeleton && !depth(5).preserve_docs);
        assert!(depth(6).skeleton && depth(6).preserve_docs);
        assert_eq!(depth(9).max_lines, 0);
        assert_eq!(depth(200).level, 9); // clamp
    }

    #[test]
    fn token_estimate_is_chars_over_four() {
        let s = "a".repeat(400);
        assert_eq!(estimate_tokens(&s, "rs"), 100);
    }

    #[test]
    fn truncate_marks_omissions() {
        let body = (0..10)
            .map(|i| i.to_string())
            .collect::<Vec<_>>()
            .join("\n");
        let out = truncate_lines(&body, 3);
        assert!(out.contains("[... 7 lines omitted ...]"));
        assert!(out.starts_with("0\n1\n2"));
    }

    #[test]
    fn skeleton_keeps_rust_signatures_drops_bodies() {
        let src = "pub fn add(a: i32, b: i32) -> i32 {\n    let x = a + b;\n    x\n}\n\nstruct S {\n    field: u8,\n}\n";
        let out = skeletonize(src, "x.rs", false);
        assert!(out.contains("pub fn add"));
        assert!(out.contains("struct S"));
        assert!(out.contains("[... "));
        assert!(!out.contains("let x = a + b"));
    }

    #[test]
    fn skeleton_leaves_unknown_lang_alone() {
        let src = "some prose\nmore prose\n";
        assert_eq!(skeletonize(src, "x.txt", false), src);
    }

    #[test]
    fn budget_keeps_focus_whole_trims_periphery() {
        let big = "fn a() {\n".to_string() + &"    x();\n".repeat(200) + "}\n";
        let cands = vec![
            Candidate {
                rel: "focus.rs".into(),
                body: big.clone(),
                focus: true,
                tokens: estimate_tokens(&big, "rs"),
            },
            Candidate {
                rel: "peri.rs".into(),
                body: big.clone(),
                focus: false,
                tokens: estimate_tokens(&big, "rs"),
            },
        ];
        // Budget only large enough for the focus file.
        let budget = estimate_tokens(&big, "rs") + 10;
        let p = plan(&cands, budget);
        assert!(p.full.contains(&"focus.rs".to_string()));
        // periphery did not fit whole â†’ skeletonized or dropped, never full.
        assert!(!p.full.contains(&"peri.rs".to_string()));
    }
}

//! The engine contract (DESIGN Â§4): one attempt of one reviewer, the exact argv the plugin
//! builds for the subprocess engines, and the validated v1 reply.
//!
//! An [`Engine`] reports its [`Capabilities`] (including how it takes its prompt,
//! [`PromptDelivery`]), plans a launch for a [`Request`] ([`Engine::plan`] -> a
//! [`LaunchPlan`], a subprocess argv or an `http` request), runs a turn checked by
//! [`Engine::precheck`], and continues a conversation ([`Engine::continue_turn`]) - all
//! carried by a [`TurnRequest`] that keeps the resolved request, the ids, the [`TurnKind`]
//! and the [`Continuation`]. A turn's result is an [`AttemptOutcome`], not a bare reply, so
//! a timeout, a launch failure, a provider failure and a cancellation are first-class
//! (F02-11/F07-5).
//!
//! Subprocess engines wrap the CLIs exactly as `codex-consult.ps1` / `New-AgyArgv` /
//! `New-MuseArgv` do: codex takes the prompt on plain stdin and a `fork <thread>` /
//! `resume <thread>` subcommand *after* every exec-level option (with `-` for stdin); agy
//! takes one NDJSON `{"event":"user",...}` line on stdin and has no fork; muse takes a
//! prompt file and has no fork. The `http` engine builds one OpenAI-compatible request from
//! a reviewer pack ([`HttpPlan`], M7) and its continuation is replay (the retained pack
//! plus the prior reply).
//!
//! Ids (DESIGN Â§4 "Identity"): [`ConsultationId`] is one brief + one reviewer; [`AttemptId`]
//! is one engine call (a retry is a NEW attempt with the same inputs, no redraw);
//! [`ConversationId`] is the engine thread for CLI engines, or a C3-owned transcript for
//! `http`. A [`Mode::Resume`]/[`Mode::Fork`] carries the [`Lineage`] of the thread it names
//! so crossing lineages is refusable (F07-8), and a returned conversation is tagged with a
//! [`ConversationTrust`] so the runtime knows whether it may be resumed.

use std::path::PathBuf;

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

use crate::ledger::{ProviderFailure, Usage};
use crate::lineage::format_reviewer_lineage;

/// The engines (DESIGN Â§4; 0.6.0 adds `claude`). `codex` is the default.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum EngineKind {
    Codex,
    Agy,
    Muse,
    /// (0.6.0, wave 29) Claude Code headless: `claude -p --output-format stream-json`, the prompt
    /// on stdin, the schema TEXT in `--json-schema`, a minted `--session-id` for a new thread.
    Claude,
    Http,
}

/// How a reviewer receives the reply schema.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum SchemaTransport {
    /// Codex `--output-schema` / muse `--output-schema`.
    OutputSchema,
    /// agy `--json-schema` (a native structured-output request).
    Native,
    /// The schema is described in the prompt only.
    PromptOnly,
}

/// How an engine takes its prompt (F02-8/F03-6/F04-7). codex: plain stdin; agy: one NDJSON
/// `{"event":"user","message":{"content":...}}` line on stdin
/// (`ConvertTo-AgyStdin`); muse: a `--prompt-file` (stdin is empty).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum PromptDelivery {
    /// The prompt text is written verbatim to stdin (codex).
    Stdin,
    /// One newline-terminated NDJSON user-message line is written to stdin (agy).
    StdinNdjsonLine,
    /// The prompt is a file named in the argv; stdin is empty (muse).
    PromptFile,
}

/// What an engine can do (DESIGN Â§4: `capabilities()`).
#[derive(Debug, Clone)]
pub struct Capabilities {
    /// The engine keeps conversation threads (a reply can be resumed/forked).
    pub threads: bool,
    /// Forking a thread is supported (codex only).
    pub fork: bool,
    /// Resuming a thread is supported natively.
    pub resume: bool,
    /// How the prompt reaches the engine.
    pub prompt_delivery: PromptDelivery,
    /// The schema transports the engine accepts, in preference order.
    pub schema_transport: Vec<SchemaTransport>,
    /// The effort vocabulary label (`openai`, `model-tier`, `muse`, ...).
    pub effort_vocabulary: &'static str,
    /// The engine runs its reviewer in a read-only sandbox.
    pub sandbox: bool,
    /// The handoff/file prefix for this engine (`codex`, `agy`, `muse`, `http`).
    pub file_prefix: &'static str,
}

/// The capability table for an engine, from `$script:Engines` (and DESIGN Â§4 for `http`).
pub fn capabilities(kind: EngineKind) -> Capabilities {
    match kind {
        EngineKind::Codex => Capabilities {
            threads: true,
            fork: true,
            resume: true,
            prompt_delivery: PromptDelivery::Stdin,
            schema_transport: vec![SchemaTransport::OutputSchema, SchemaTransport::PromptOnly],
            effort_vocabulary: "openai",
            sandbox: true,
            file_prefix: "codex",
        },
        EngineKind::Agy => Capabilities {
            threads: true,
            fork: false,
            resume: true,
            prompt_delivery: PromptDelivery::StdinNdjsonLine,
            schema_transport: vec![SchemaTransport::Native, SchemaTransport::PromptOnly],
            effort_vocabulary: "model-tier",
            // agy --sandbox restricts the terminal only; the bridge's tree check enforces
            // read-only. The capability is "runs read-only" as the bridge guarantees it.
            sandbox: true,
            file_prefix: "agy",
        },
        EngineKind::Muse => Capabilities {
            threads: true,
            fork: false,
            resume: true,
            prompt_delivery: PromptDelivery::PromptFile,
            schema_transport: vec![SchemaTransport::OutputSchema, SchemaTransport::PromptOnly],
            effort_vocabulary: "muse",
            sandbox: true,
            file_prefix: "muse",
        },
        EngineKind::Claude => Capabilities {
            threads: true,
            fork: true,
            resume: true,
            prompt_delivery: PromptDelivery::Stdin,
            schema_transport: vec![SchemaTransport::Native, SchemaTransport::PromptOnly],
            effort_vocabulary: "claude",
            // --restricted --tools Read,Grep,Glob, proven by every init event; the bridge's tree
            // check fails a run that changed anything (D1).
            sandbox: true,
            file_prefix: "claudecode",
        },
        EngineKind::Http => Capabilities {
            threads: false,
            fork: false,
            // Continuation is replay (the retained pack + the prior reply), not a native
            // thread resume; reported as unsupported.
            resume: false,
            // The http engine sends a request body, not stdin; delivery is not a CLI shape,
            // but the prompt still travels in the request, so `Stdin` is the nearest label.
            prompt_delivery: PromptDelivery::Stdin,
            schema_transport: vec![SchemaTransport::OutputSchema, SchemaTransport::PromptOnly],
            effort_vocabulary: "openai",
            // The http engine never receives tools (DESIGN Â§3 invariant 2).
            sandbox: false,
            file_prefix: "http",
        },
    }
}

/// A reviewer lineage key (`provider :: model [engine]`), used to refuse resuming/forking
/// across lineages (F07-8).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Lineage(pub String);

/// The launch mode for a CLI engine. `Resume`/`Fork` carry the [`Lineage`] of the thread so
/// a cross-lineage resume/fork is refusable.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Mode {
    /// A fresh thread.
    New,
    /// Resume a known thread on a known lineage.
    Resume { thread: String, lineage: Lineage },
    /// Fork a known thread on a known lineage (codex only).
    Fork { thread: String, lineage: Lineage },
}

/// One consultation id (one brief, one reviewer). The prompt's last line carries it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ConsultationId(pub String);

/// One attempt id (one engine call). A retry is a new [`AttemptId`] with the same inputs.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AttemptId(pub String);

/// One conversation id (the engine thread for CLI engines; a C3 transcript for `http`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ConversationId(pub String);

/// A request for one attempt. Some fields are engine-specific (documented per field).
#[derive(Debug, Clone)]
pub struct Request {
    /// The full prompt text (its last line is `Consultation id: <id>`).
    pub prompt: String,
    /// The brief file, for the record.
    pub brief_path: Option<PathBuf>,
    pub model: String,
    pub provider: String,
    /// The engine this request runs on (used for the lineage key and the fork check).
    pub engine: EngineKind,
    /// The effort value to send (already mapped to the engine's vocabulary), if any.
    pub effort: Option<String>,
    /// The run timeout, in seconds.
    pub timeout_sec: f64,
    pub mode: Mode,
    /// The sandbox label (codex: `read-only`/`workspace-write`).
    pub sandbox: String,
    /// The reply schema file, when a schema transport is used.
    pub schema_path: Option<PathBuf>,
    /// Applied `-CodexConfig` items (`key=value`); codex `-c` args, passed through verbatim.
    pub extra_config: Vec<String>,
    /// (wave 8 = plugin wave 30) The bridge's own codex `-c` items placed right after `-m`, before
    /// the identity pins and the user's items: `features.multi_agent=false` unless the user's
    /// `-CodexConfig` names `features.multi_agent` (theirs wins). Empty for every other engine.
    pub agent_config: Vec<String>,
    /// codex `-o <path>`: where the last agent message is written.
    pub output_last_message: Option<PathBuf>,
    /// muse `--prompt-file <path>`: the prompt file.
    pub prompt_file: Option<PathBuf>,
    /// muse `--max-model-steps <n>`; (0.6.0) claude `--max-turns <n>`.
    pub max_model_steps: Option<u32>,
    /// (0.6.0, wave 29, item 2) claude: the id the bridge minted for a NEW thread
    /// (`--session-id`), known before the first byte; `None` for every other engine and turn.
    pub new_thread: Option<String>,
    /// (wave 29, item 1) claude: the directories outside the repository the reviewer must read
    /// (`--add-dir`).
    pub add_dirs: Vec<String>,
}

impl Request {
    /// The reviewer lineage key for this request (`provider :: model [engine]`).
    pub fn lineage(&self) -> Lineage {
        Lineage(format_reviewer_lineage(
            &self.provider,
            &self.model,
            engine_token(self.engine),
        ))
    }
}

fn engine_token(kind: EngineKind) -> &'static str {
    match kind {
        EngineKind::Codex => "codex",
        EngineKind::Agy => "agy",
        EngineKind::Muse => "muse",
        EngineKind::Claude => "claude",
        EngineKind::Http => "http",
    }
}

/// What kind of turn this is (F02-10/F08-6): the primary attempt or one of the three
/// secondary-turn mechanisms.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum TurnKind {
    /// The first turn of an attempt.
    Primary,
    /// A continuation after a timeout kill.
    TimeoutContinuation,
    /// A retry after a tool was auto-denied and the first turn produced nothing.
    DenialRetry,
    /// A repair turn that converts a prose reply into the structured object.
    FormatRepair,
}

/// How a continuation reaches the engine (F02-10/F04-7): a native thread resume, or - for
/// the `http` engine - replay of the retained pack plus the prior reply.
#[derive(Debug, Clone)]
pub enum Continuation {
    /// Resume the engine's own conversation thread.
    Native(ConversationId),
    /// Replay: the retained pack (by content hash) and the prior reply text.
    Replay {
        pack_hash: String,
        prior_reply: String,
    },
}

/// A request for a secondary turn or continuation. It carries the full resolved [`Request`],
/// the ids, the [`TurnKind`] and (for a continuation) the [`Continuation`], so no launch
/// setting, retry policy or replay input is dropped (F02-10).
#[derive(Debug, Clone)]
pub struct TurnRequest {
    pub request: Request,
    pub consultation: ConsultationId,
    pub attempt: AttemptId,
    pub kind: TurnKind,
    /// `None` for a primary turn; `Some` for a continuation/resume.
    pub continuation: Option<Continuation>,
}

/// The argv the engine will run: the launcher plus its arguments (the launcher is resolved
/// on PATH separately). `args` is everything after the launcher.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Argv {
    pub command: String,
    pub args: Vec<String>,
}

impl Argv {
    /// The whole argv as one display string (`codex exec --sandbox read-only ... -`).
    pub fn to_command_string(&self) -> String {
        let mut s = self.command.clone();
        for a in &self.args {
            s.push(' ');
            s.push_str(a);
        }
        s
    }
}

/// The `http` engine's plan: one OpenAI-compatible request built from a reviewer pack (M7).
/// The pack pipeline and the exact wire body land in the runtime; this carries the resolved
/// identity and prompt the request is built from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct HttpPlan {
    pub provider: String,
    pub model: String,
    pub prompt: String,
    pub schema_path: Option<PathBuf>,
    pub effort: Option<String>,
}

/// What [`Engine::plan`] produces: a subprocess argv, or an `http` request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LaunchPlan {
    Subprocess(Argv),
    Http(HttpPlan),
}

/// Whether a returned conversation id may be trusted for a resume (F02-11).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ConversationTrust {
    /// A conversation id the engine confirmed (safe to resume/fork).
    Verified(ConversationId),
    /// A candidate id observed but not confirmed (e.g. a killed turn); resume at your risk.
    Candidate(ConversationId),
    /// No conversation id at all.
    None,
}

/// One reply from an attempt.
#[derive(Debug, Clone)]
pub struct Reply {
    /// The verbatim reply text (the verified structured or the salvaged prose).
    pub raw_text: String,
    /// The parsed, validated v1 reply, when the attempt produced a valid structured object.
    pub structured: Option<StructuredReply>,
    /// The raw event stream file (`.events.jsonl`).
    pub events_path: PathBuf,
    /// Token usage, when the engine reports it.
    pub usage: Option<Usage>,
    /// Wall time in seconds.
    pub wall_seconds: f64,
    /// The conversation this reply came on, and whether it may be resumed.
    pub conversation: ConversationTrust,
}

/// The result of one attempt (F02-11/F07-5): a completed reply, a timeout with a salvaged
/// partial and the survivors it could not kill, a launch failure (with whether a child was
/// left behind), a provider failure, or a cancellation.
#[derive(Debug, Clone)]
pub enum AttemptOutcome {
    Completed(Reply),
    TimedOut {
        partial: Option<String>,
        survivors: Vec<u32>,
        conversation: ConversationTrust,
        /// The measured wall time of the killed turn (`[math]::Round(..., 1)`).
        wall_seconds: f64,
        /// (wave 27c D16, 28c D8, 28e E1/E23) What the process-tree kill could confirm; `None`
        /// when no process was killed (the http engine has none).
        kill: Option<KillCheck>,
    },
    /// (wave 26b, D10/D12) A subprocess turn the bridge stopped for a reason other than its
    /// wall-clock timeout: the stall cut (`--stall-sec`: no event for that long while the process
    /// lived) or the operator's `-Kick`. Carries the same salvage/survivors/conversation the
    /// [`TimedOut`] path does; [`StopKind`] tells them apart (a stall is stopped like a timeout â€”
    /// one continuation turn follows; a kick has no continuation and is class `operator`).
    Stopped {
        kind: StopKind,
        partial: Option<String>,
        survivors: Vec<u32>,
        conversation: ConversationTrust,
        wall_seconds: f64,
        /// What the process-tree kill could confirm (as [`AttemptOutcome::TimedOut`]).
        kill: Option<KillCheck>,
    },
    LaunchFailed {
        /// Whether a child process was left behind by the failed launch.
        child_exists: bool,
        message: String,
    },
    ProviderFailure {
        failure: ProviderFailure,
        /// The child's raw process exit code, for the plugin's `codex exit N` framing on a
        /// secondary (timeout-continuation / format-repair) turn. `None` when unknown.
        exit_code: Option<i32>,
    },
    Cancelled,
}

/// (wave 27c D16; 28c D8; 28e E1, E23) What a process-tree kill could confirm
/// (`Stop-ProcessTreeChecked`'s result; the pids still alive after it travel beside it as the
/// outcome's `survivors`). `confirmed` only when the root exited and every known descendant is gone
/// (and, where the children could not be enumerated, the tree-kill fallback reported the whole
/// tree terminated). A descendant whose start time could not be read is neither killed by its pid
/// nor counted as gone: it is listed in `unverified` (the kill is then "not confirmed: start time
/// of pid <n> unreadable"). `why` says why the kill is not confirmed (`""` when it is).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct KillCheck {
    /// The pid of the tree's root (the process the bridge started).
    pub root_pid: u32,
    pub confirmed: bool,
    pub why: String,
    /// Descendants whose start time could not be read (`Unverified`).
    pub unverified: Vec<u32>,
    /// (wave 7b, F38-1) The kill did NOT happen: the record naming the tree could be written
    /// nowhere, so the tree was left alive as the evidence (`why` says so; the live pids travel
    /// as the outcome's `survivors`). Never set by a kill that ran.
    pub not_killed: bool,
}

impl KillCheck {
    /// A kill of `root_pid` that is confirmed (nothing left, nothing unverified).
    pub fn confirmed(root_pid: u32) -> KillCheck {
        KillCheck {
            root_pid,
            confirmed: true,
            why: String::new(),
            unverified: Vec::new(),
            not_killed: false,
        }
    }
}

/// Why a subprocess turn was stopped short of a natural exit or a wall-clock timeout
/// (`AttemptOutcome::Stopped`).
#[derive(Debug, Clone)]
pub enum StopKind {
    /// The stall cut fired: the event stream produced no event for `silent_seconds` while the
    /// process lived (with the tool-call suspension of wave 26c D3). `last_event` is the ISO time
    /// of the last event seen before the kill, `None` when none was seen.
    Stall {
        silent_seconds: i64,
        /// (wave 27c, D6) Seconds a tool call had been open at the stall kill (`0` when none).
        tool_open_seconds: i64,
        /// (wave 28b, D12) The tool call(s) open at the stall kill, `""` when none.
        open_tools: String,
        last_event: Option<String>,
    },
    /// The operator stopped the run with `-Kick`.
    Kick,
    /// (wave 8 = plugin wave 30, T15) The quota budget stopped the main turn: the 5-hour window of
    /// the run's rollout, observed during the turn, reached `-Budget` with its reset ahead.
    Budget { window: crate::quota::PrimaryWindow },
}

